<section class="page-section"><div class="container narrow"><div class="section-title"><h1><?= e($title) ?></h1><a class="btn btn-ghost" href="<?= e(url('/admin')) ?>">Quay lại quản trị</a></div><p>“Ngừng sử dụng” là xóa mềm để không phá khóa ngoại và dữ liệu tin đã đăng. Có thể kích hoạt lại.</p>
<?php foreach($catalogs as $kind=>$items): ?><section class="surface-card mb-4"><h2><?= $kind==='type'?'Loại chỗ ở':'Tiện nghi' ?></h2>
<?php foreach(array_merge([['id'=>0,'name'=>'','detail'=>'','is_active'=>1]],$items) as $item): ?>
<form class="border-top py-3" method="post" action="<?= e(url('/admin/catalog')) ?>"><?= csrf_field() ?><input type="hidden" name="kind" value="<?= $kind ?>"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><h3 class="h6"><?= $item['id']?'#'.(int)$item['id']:'Thêm mới' ?></h3>
<label for="catalog-name-<?= $kind ?>-<?= (int)$item['id'] ?>">Tên</label><input class="form-control mb-2" id="catalog-name-<?= $kind ?>-<?= (int)$item['id'] ?>" name="name" value="<?= e($item['name']) ?>" maxlength="80" required>
<label for="catalog-detail-<?= $kind ?>-<?= (int)$item['id'] ?>"><?= $kind==='type'?'Mô tả':'Mã icon (không bắt buộc)' ?></label><input class="form-control mb-2" id="catalog-detail-<?= $kind ?>-<?= (int)$item['id'] ?>" name="detail" value="<?= e($item['detail']) ?>" maxlength="<?= $kind==='type'?5000:80 ?>">
<label><input type="checkbox" name="active" value="1" <?= $item['is_active']?'checked':'' ?>> Đang sử dụng</label><div class="action-row"><button class="btn btn-primary"><?= $item['id']?'Lưu thay đổi':'Thêm danh mục' ?></button><?php if($item['id']): ?><button class="btn btn-outline-danger" name="active" value="0" data-confirm="Ngừng sử dụng danh mục này? Các tin hiện có vẫn được giữ.">Ngừng sử dụng</button><?php endif; ?></div></form>
<?php endforeach; ?></section><?php endforeach; ?></div></section>
